<template><main class="shop-page detail-page"><p v-if="loading">Cargando producto…</p><section v-else-if="product" class="product-detail"><div class="detail-image"><img v-if="product.image_url" :src="product.image_url" :alt="product.name"><PackageOpen v-else :size="72" aria-label="Producto sin imagen" /></div><div><p class="eyebrow">{{ product.categories?.name }}</p><h1>{{ product.name }}</h1><p class="detail-price">{{ price }}</p><p class="stock" :class="product.stock <= 0 ? 'out' : product.stock <= 5 ? 'low' : 'available'">{{ stock }}</p><p class="description">{{ product.description || 'Sin descripción disponible.' }}</p><RouterLink to="/shop" class="back-link">← Volver a la tienda</RouterLink></div></section><section v-else class="not-found"><h1>Producto no encontrado</h1><p>Es posible que ya no esté disponible.</p><RouterLink to="/shop">Volver a la tienda</RouterLink></section></main></template>
<script setup>
import { computed, onMounted, ref } from 'vue'; import { PackageOpen } from 'lucide-vue-next'; import { useRoute } from 'vue-router'; import { getProductBySlug } from '../services/products'
const route = useRoute(), product = ref(null), loading = ref(true)
const price = computed(() => new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:0}).format(product.value?.price || 0)); const stock = computed(() => product.value.stock <= 0 ? 'Agotado' : product.value.stock <= 5 ? `Poco stock (${product.value.stock})` : `En stock (${product.value.stock})`)
onMounted(async () => { const { data } = await getProductBySlug(route.params.slug); product.value = data; loading.value = false; document.title = data ? `${data.name} | Rincón de la esperanza` : 'Producto no encontrado' })
</script>
